/* Objeto multilíngue para conteúdo de dados (seed) */
export const ml = (pt, en, es, fr) => ({ pt, en, es, fr });

/* Moeda por idioma: os valores-base são em BRL e são convertidos para a
   moeda do idioma ativo (taxas de câmbio ilustrativas, fixas para a demo).
   PT → R$ (BRL) · EN → $ (USD) · ES/FR → € (EUR) */
const DEFAULT_RATES = { usd: 0.185, eur: 0.17 };
let rates = {
  usd: parseFloat(lsGet('meatende.rate.usd')) || DEFAULT_RATES.usd,
  eur: parseFloat(lsGet('meatende.rate.eur')) || DEFAULT_RATES.eur
};
export function getRates() { return { ...rates }; }
export function setRates(usd, eur) {
  if (Number(usd) > 0) rates.usd = Number(usd);
  if (Number(eur) > 0) rates.eur = Number(eur);
  lsSet('meatende.rate.usd', rates.usd);
  lsSet('meatende.rate.eur', rates.eur);
}
export function currencyInfo() {
  const code = current === 'en' ? 'USD' : (current === 'es' || current === 'fr') ? 'EUR' : 'BRL';
  const rate = current === 'en' ? rates.usd : (current === 'es' || current === 'fr') ? rates.eur : 1;
  return { code, rate };
}
export function money(v, compact = false) {
  const { code, rate } = currencyInfo();
  const val = (Number(v) || 0) * rate;
  return new Intl.NumberFormat(locale(), {
    style: 'currency', currency: code,
    maximumFractionDigits: compact ? 0 : 2,
    notation: compact && val >= 10000 ? 'compact' : 'standard'
  }).format(val);
}

/* Resolve valor multilíngue ou marcador de moeda */
export function L(v) {
  if (v == null) return '';
  if (typeof v === 'object') {
    if ('__m' in v) return money(v.__m, v.__c);
    return v[getLang()] ?? v.pt ?? '';
  }
  return String(v);
}

function lsGet(key) { try { return localStorage.getItem(key); } catch { return null; } }
function lsSet(key, val) { try { localStorage.setItem(key, val); } catch {} }

let current = lsGet('meatende.lang') || 'pt';
if (!(current in IDX)) current = 'pt';

export function getLang() { return current; }

export function setLang(code) {
  if (!(code in IDX)) return;
  current = code;
  lsSet('meatende.lang', code);
  document.documentElement.lang = code === 'pt' ? 'pt-BR' : code;
}

export function t(key, params) {
  const entry = D[key];
  let s = entry ? (entry[IDX[current]] || entry[0]) : key;
  if (params) for (const k in params) s = s.replaceAll('{' + k + '}', L(params[k]));
  return s;
}

export function locale() {
  return { pt: 'pt-BR', en: 'en-US', es: 'es-ES', fr: 'fr-FR' }[current];
}
